text:
{
  "jobs": [
    {
      "text": "Обеспечить непрерывную связь с семьей (детьми и женой) во время отпуска за границей.",
      "quote": "Мне главное, чтобы связь работала без лишних заморочек, а то потеряю детей из вида и начну паниковать."
    },
    {
      "text": "Получить доступ к интернету и звонкам сразу после прилета, не тратя время на сложные настройки.",
      "quote": "В аэропорту я вижу живого человека, беру пластик в руки и сразу вставляю в телефон, тут нет риска остаться без интернета из-за кода активации или сбоя сайта."
    },
    {
      "text": "Избежать необходимости изучать новые технологии или приложения в условиях ограниченного времени.",
      "quote": "Никаких приложений скачивать не пришлось, поэтому и проблем не возникло."
    }
  ],
  "pains": [
    {
      "text": "Страх технической ошибки при настройке eSIM, ведущей к потере основного номера или полной изоляции.",
      "quote": "А с eSIM мне кажется, что можно случайно удалить основной номер или остаться без связи вообще."
    },
    {
      "text": "Невозможность получить быструю и понятную помощь в случае сбоя удаленно.",
      "quote": "Я боюсь, что поддержка будет висеть на линии часами или говорить по-английски с непонятным акцентом."
    },
    {
      "text": "Ограничения устройств членов семьи (отсутствие поддержки eSIM у жены).",
      "quote": "У жены телефон вообще не поддерживает эту технологию, так что нам всё равно пришлось бы покупать физические карты..."
    },
    {
      "text": "Тревога из-за скрытых платежей и непредсказуемых расходов.",
      "quote": "Мне важно было услышать слово «включено», потому что я боюсь скрытых платежей за перебор гигабайтов."
    }
  ],
  "current_solutions": [
    {
      "text": "Покупка физических SIM-карт местных операторов в киосках аэропорта по прилету.",
      "quote": "В прошлый раз в Анталье мы просто купили три местные симки в аэропорту по прилёту, это было быстрее всего."
    },
    {
      "text": "Использование Wi-Fi в отеле для мессенджеров вместо платных роуминговых звонков.",
      "quote": "Мы договорились, что звонить будем только через мессенджеры по Wi-Fi в отеле, чтобы не переплачивать за минуты."
    },
    {
      "text": "Отключение роуминга перед вылетом для контроля расходов.",
      "quote": "...а роуминг отключил за день до рейса, чтобы случайно не начать тратить деньги в аэропорту."
    }
  ],
  "barriers": [
    {
      "text": "Барьер понимания: отсутствие знаний о процессе активации eSIM и страх необратимых ошибок.",
      "quote": "С eSIM я вообще не дружу: слышал про неё, но сам ставить боюсь..."
    },
    {
      "text": "Барьер выбора/доверия: недоверие к цифровым каналам продаж и сторонним сервисам из-за отсутствия физического контакта.",
      "quote": "Доверяю только оператору связи в аэропорту — он живой человек, который объяснит на пальцах, как активировать карту, и гарантирует, что она заработает."
    },
    {
      "text": "Барьер оплаты: готовность переплатить за надежность и простоту, отказ от экономии ради рискованных решений.",
      "quote": "Лучше уж переплатить за роуминг или взять местную карту, чем рисковать связью с семьёй из-за какой-то непонятной настройки."
    }
  ],
  "triggers": [
    {
      "text": "Необходимость быть на связи с детьми в чужой стране.",
      "quote": "Телефон для меня — это просто способ быть на связи... а то потеряю детей из вида и начну паниковать."
    },
    {
      "text": "Желание избежать сложностей и стресса в отпуске.",
      "quote": "В отпуске у меня нет времени читать инструкции или звонить в поддержку, чтобы объяснять свои ошибки."
    }
  ],
  "words": [
    "заморочки",
    "живой человек",
    "понятный и надёжный путь",
    "скрытые платежи",
    "цена за спокойствие",
    "вставил — заработало",
    "паниковать",
    "рисковать"
  ],
  "surprises": [
    "Респондент предпочитает физический контакт (стойка оператора) даже если это дороже и требует стояния в очереди, считая это более надежным, чем цифровая доставка eSIM.",
    "Отсутствие реального негативного опыта с eSIM (риск гипотетический), но сила страха достаточна для полного отказа от технологии.",
    "Готовность платить за 'спокойствие' и простоту интерфейса выше, чем стремление к минимизации финансовых затрат на связь."
  ]
}
